export function getQuestionsForTest(examSlug: string, testId: string): Question[] {
  const checkedBank = CHECKED_TEST_BANKS[`${examSlug}/${testId}`];
  if (checkedBank) return checkedBank;

  // Demo sets reuse the old sample bank. They are labelled as demos in the UI
  // and must not be presented as complete or officially sourced papers.
  const bank = QUESTION_BANK[examSlug as ExamSlug] ?? [];
  if (bank.length === 0) return [];
  const match = testId.match(/(\d+)$/);
  const testNum = match ? parseInt(match[1], 10) : 1;
  const offset = ((testNum - 1) * 5) % bank.length;
  return [...bank.slice(offset), ...bank.slice(0, offset)];
}

// Placeholder question bank: original practice questions, not sourced from
// any real paper. Replace with real content from the question bank once
// wired in (see README). Sections match ExamConfig.sections exactly so the
// results screen can group scores by section.

export interface QuestionSource {
  kind: 'original' | 'official-paper';
  reference: string;
  url: string;
  checkedOn: string;
}

export interface Question {
  id?: string;
  section: string;
  topic?: string;
  difficulty?: 'easy' | 'medium' | 'hard';
  question: string;
  options: string[];
  correctIndex: number;
  answerType?: 'mcq' | 'multi-select' | 'numerical';
  correctValue?: string;
  correctIndices?: number[];
  partialMarking?: boolean;
  // Formula used when partialMarking is true and the selected options are a
  // proper, correct-only subset. Unset (default): 1 point per correctly
  // selected option, the existing JEE Advanced/PTE convention, where the
  // question's own `marks` need not equal its correct-option count.
  // 'proportional': marks * selectedCorrect / totalCorrect, the WBJEE
  // Category 3 rule, where `marks` is a fixed cap independent of how many
  // options happen to be correct on a given question.
  partialCreditMode?: 'proportional';
  maxDecimalPlaces?: number;
  marks?: number;
  negativeMarking?: number;
  explanation: string;
  source?: QuestionSource;
}

