// Practice-family tests (quick / topic / difficulty) are deterministic slices of the
// same syllabus-checked question pools used above: no new content, no randomness
// (this stays a static export, so every build must produce the same slice).
const SSC_CGL_TIER1_POOLS: Record<string, Question[]> = {
  'General Intelligence and Reasoning': [...SSC_CGL_TIER1_REASONING_1, ...SSC_CGL_TIER1_REASONING_2, ...SSC_CGL_TIER1_REASONING_3],
  'General Awareness': [...SSC_CGL_TIER1_GENERAL_AWARENESS_1, ...SSC_CGL_TIER1_GENERAL_AWARENESS_2, ...SSC_CGL_TIER1_GENERAL_AWARENESS_3],
  'Quantitative Aptitude': [...SSC_CGL_TIER1_QUANTITATIVE_1, ...SSC_CGL_TIER1_QUANTITATIVE_2, ...SSC_CGL_TIER1_QUANTITATIVE_3],
  'English Comprehension': [...SSC_CGL_TIER1_ENGLISH_1, ...SSC_CGL_TIER1_ENGLISH_2, ...SSC_CGL_TIER1_ENGLISH_3],
};

function byDifficulty(pool: Question[], levels: Array<Question['difficulty']>, cap: number): Question[] {
  return pool.filter((q) => levels.includes(q.difficulty)).slice(0, cap);
}

function byTopics(pool: Question[], topics: string[], cap = Infinity): Question[] {
  const wanted = new Set(topics.map((t) => t.toLowerCase()));
  return pool.filter((q) => q.topic && wanted.has(q.topic.toLowerCase())).slice(0, cap);
}

